<?php
namespace App\Http\Controllers\Web;
use App\Http\Controllers\Controller;use App\Models\User;use App\Services\Accounts\AdminAccess;use App\Services\Admin\OperationAudit;use App\Services\JourneyStore;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
final class BuddyCommunityController extends Controller {
 public function index(Request $r){abort_unless(app(AdminAccess::class)->allows($r->user()),403);$audits=DB::table('buddy_audits')->orderByDesc('id')->limit(50)->get(['id','activity_id','action','facts','created_at']);$comments=DB::table('moderation_reports as r')->join('status_post_comments as c','c.id','=','r.target_status_comment_id')->where('r.category','status_comment')->orderByDesc('r.id')->limit(20)->get(['r.id as report_id','r.status as report_status','c.id','c.body','c.state','c.revision']);$publications=DB::table('buddy_discovery_publications as p')->join('buddy_activities as a','a.id','=','p.activity_id')->where('p.state','PUBLISHED')->where('p.expires_at','>',now())->orderByDesc('p.id')->limit(20)->get(['p.id','p.author_label','p.expires_at','a.type','a.subject','a.revision']);return view('admin.buddy-community',compact('audits','comments','publications'));}
 public function withdrawDiscovery(Request $r,int $publication){
  $d=$r->validate(['revision'=>'required|integer|min:1','reason'=>'required|string|max:500','confirm'=>'required|accepted']);
  abort_unless(trim($d['reason'])!=='',422,'reason is required');
  app(\App\Services\BuddyService::class)->adminWithdrawDiscovery((int)$r->user()->id,$publication,(int)$d['revision'],trim($d['reason']));
  return redirect()->route('admin.buddy-community');
 }
 public function hide(Request $r,int $reportId){$d=$r->validate(['revision'=>'required|integer|min:1','reason'=>'required|string|max:500','confirm'=>'required|accepted']);$candidate=DB::table('moderation_reports as r')->join('status_post_comments as c','c.id','=','r.target_status_comment_id')->join('status_posts as p','p.id','=','c.status_post_id')->where('r.id',$reportId)->where('r.category','status_comment')->first(['c.author_id','p.author_user_id','c.id']);abort_unless($candidate,404);DB::transaction(function()use($r,$reportId,$d,$candidate){app(JourneyStore::class)->users([(int)$r->user()->id,(int)$candidate->author_id,(int)$candidate->author_user_id],true);abort_unless(app(AdminAccess::class)->allows(User::find($r->user()->id)),403);$report=DB::table('moderation_reports')->where('id',$reportId)->where('target_status_comment_id',$candidate->id)->where('category','status_comment')->lockForUpdate()->first();$c=DB::table('status_post_comments')->where('id',$candidate->id)->where('author_id',$candidate->author_id)->lockForUpdate()->first();abort_unless($report&&$report->status==='new'&&$c&&$c->state==='ACTIVE'&&(int)$c->revision===(int)$d['revision'],409,'stale report');DB::table('status_post_comments')->where('id',$c->id)->update(['state'=>'HIDDEN','revision'=>$c->revision+1,'updated_at'=>now()]);DB::table('moderation_reports')->where('id',$reportId)->update(['status'=>'resolved','resolved_by_user_id'=>$r->user()->id,'resolved_at'=>now(),'updated_at'=>now()]);OperationAudit::record((int)$r->user()->id,'status_comment.hide','status_comment',$c->id,trim($d['reason']),(int)$c->revision,['state'=>'ACTIVE'],['state'=>'HIDDEN']);},3);return redirect()->route('admin.buddy-community');}
}
